import{_ as u,a0 as a,w as i,s as l,ao as s,I as n,x as r,a1 as p,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu","title":"Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序","tag":"201501","desc":""},"relativePath":"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu.md","filePath":"[post].md"}'),d={name:"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu.md"};function b(A,t,m,x,f,T){const o=a("Link");return i(),l("div",null,[t[11]||(t[11]=s(`<h1 id="linux有問必答-如何禁止ubuntu的apport內部錯誤報告程序" tabindex="-1">Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序 <a class="header-anchor" href="#linux有問必答-如何禁止ubuntu的apport內部錯誤報告程序" aria-label="Permalink to “Linux有問必答：如何禁止Ubuntu的Apport內部錯誤報告程序”">​</a></h1><blockquote><p><strong>問題</strong>：在桌面版Ubuntu中，我經常遇到一些彈窗窗口，警告我Ubuntu發生了內部錯誤，問我要不要發送錯誤報告。每次軟件崩潰都要煩擾我，我如何才能關掉這個錯誤報告功能呢？</p></blockquote><p>Ubuntu桌面版預裝了Apport，它是一個錯誤收集系統，會收集軟件崩潰、未處理異常和其他，包括程序bug，併為調試目的生成崩潰報告。當一個應用程序崩潰或者出現Bug時候，Apport就會通過彈窗警告用户並且詢問用户是否提交崩潰報告。你也許也看到過下面的消息。</p><ul><li>&quot;Sorry, the application XXXX has closed unexpectedly.&quot;</li><li>&quot;對不起，應用程序XXXX意外關閉了。&quot;</li><li>&quot;Sorry, Ubuntu XX.XX has experienced an internal error.&quot;</li><li>&quot;對不起，Ubuntu XX.XX 發生了一個內部錯誤。&quot;</li><li>&quot;System program problem detected.&quot;</li><li>&quot;檢測到系統程序問題。&quot;</li></ul><p><img src="https://farm9.staticflickr.com/8635/15688551119_708b23b12a_z.jpg" alt=""></p><p>也許因為應用一直崩潰，頻繁的錯誤報告會使人心煩。也許你擔心Apport會收集和上傳你的Ubuntu系統的敏感信息。無論什麼原因，你想關掉Apport的錯誤報告功能。</p><h3 id="臨時關閉apport錯誤報告" tabindex="-1">臨時關閉Apport錯誤報告 <a class="header-anchor" href="#臨時關閉apport錯誤報告" aria-label="Permalink to “臨時關閉Apport錯誤報告”">​</a></h3><p>如果你想要臨時關閉Apport，使用下列命令</p><pre><code>$ sudo service apport stop 
</code></pre><p>注意重啓Ubuntu系統Apport會繼續開啓</p><h3 id="永久關閉apport錯誤報告" tabindex="-1">永久關閉Apport錯誤報告 <a class="header-anchor" href="#永久關閉apport錯誤報告" aria-label="Permalink to “永久關閉Apport錯誤報告”">​</a></h3><p>為了永久關閉Apport，編輯/etc/default/apport，修改下列參數</p><pre><code>enabled=0
</code></pre><p>重啓你的Ubuntu系統，Apport將會自動關閉</p><p>如果你再也不會用Apport，有一種簡單的方法完全移除它</p><pre><code>$ sudo apt-get purge apport 
</code></pre><hr>`,17)),n("p",null,[t[1]||(t[1]=r("via: ",-1)),p(o,{href:"http://ask.xmodulo.com/disable-apport-internal-error-reporting-ubuntu.html"},{default:e(()=>[...t[0]||(t[0]=[r("http://ask.xmodulo.com/disable-apport-internal-error-reporting-ubuntu.html",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=r("譯者：",-1)),p(o,{href:"http://www.vicyu.net/"},{default:e(()=>[...t[2]||(t[2]=[r("VicYu/Vic020",-1)])]),_:1}),t[5]||(t[5]=r(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=r("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[r("LCTT",-1)])]),_:1}),t[9]||(t[9]=r(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[r("Linux中國",-1)])]),_:1}),t[10]||(t[10]=r(" 榮譽推出",-1))])])}const L=u(d,[["render",b]]);export{h as __pageData,L as default};
